void mainImage(out vec4 c,vec2 p) {
    c = vec4(0);
    c += texture(iChannel0,p / r) * 1.;
    c += texture(iChannel1,p / r) * 2.;
    c += texture(iChannel2,p / r) * 3.;
    c += texture(iChannel3,p / r) * 4.;
}

float random(float v0) {return fract(v0 * (fract(v0 * 7.512 + 0.426) + 2.327) * 1.512 + 0.265);}

float random(float v0,float v1) 
{return random(v1 + random(v0) * 100.);}
float random(float v0,float v1,float v2) 
{return random(v2 + random(v0,v1) * 100.);}
float random(float v0,float v1,float v2,float v3) 
{return random(v3 + random(v0,v1,v2) * 100.);}
float random(float v0,float v1,float v2,float v3,float v4) 
{return random(v4 + random(v0,v1,v2,v3) * 100.);}
float random(float v0,float v1,float v2,float v3,float v4,float v5) 
