float random(float v0,float v1,float v2,float v3,float v4,float v5,float v6,float v7) 
{return random(v7 + random(v0,v1,v2,v3,v4,v5,v6) * 100.);}


void mainCubemap(out vec4 c,vec2 UNUSED1,vec3 UNUSED2,vec3 p) {
    float l = length(p / max(max(abs(p.x),abs(p.y)),abs(p.z)));
    p /= length(p);
    c = texture(iChannel0,p);
    float i = 0.;
    vec2 randvals = vec2(random(p.x,p.y,p.z,iTime,0.) * 6.28,random(p.x,p.y,p.z,iTime,1.) * 2. - 1.);
    vec3 pole = vec3(sin(randvals.x + vec2(0,1.57)) * sqrt(1. - randvals.y * randvals.y),randvals.y);
    while(abs(dot(pole,p)) > 0.7) {
        i++;
        randvals = vec2(random(p.x,p.y,p.z,iTime,0.,i) * 6.28,random(p.x,p.y,p.z,iTime,1.,i) * 2. - 1.);
        pole = vec3(sin(randvals.x + vec2(0,1.57)) * sqrt(1. - randvals.y * randvals.y),randvals.y);
    }
    vec3 delx = normalize(cross(pole,p));
    vec3 dely = normalize(cross(delx,p));
    float dx = 0.05;
    vec4 gpx = texture(iChannel0,normalize(p + delx * dx));
    vec4 gnx = texture(iChannel0,normalize(p - delx * dx));
    vec4 gpy = texture(iChannel0,normalize(p + dely * dx));
    vec4 gny = texture(iChannel0,normalize(p - dely * dx));
    //c.x = texture(iChannel0,p + ((c.x - gnx.x) * delx + (c.x - gny.x) * dely) * dx * 10.).x;
    //c.y = texture(iChannel0,p + ((c.y - gnx.y) * delx + (c.y - gny.y) * dely) * dx * 10.).y;
    //c.z = texture(iChannel0,p + ((c.z - gnx.z) * delx + (c.z - gny.z) * dely) * dx * 10.).z;
    c += gpx + gnx + gpy + gny;
    c /= 5.;
    c.xyz += (c.yzx * c.zxy) * 0.72 - (c.xyz * c.yzx + c.xyz * c.zxy) * 1.5;
    c = clamp(c,0.,1.);
    c.xyz /= length(c.xyz) + 0.01;
    if(iFrame < int(fract(iDate.w) * 10. + 10.)) {c.xyz = vec3(random(p.x,p.y,p.z,iTime,0.),random(p.x,p.y,p.z,iTime,1.),random(p.x,p.y,p.z,iTime,2.));}
}

vec3 shine(vec3 c) {
    return (c * (1. - length(c)) - 0.014) * 4.;
}

void mainImage(out vec4 c,vec2 p) {
    float rsp = 1.3;
    c = vec4(0);
    p = (p - r / 2.) / r.y * 2.1;
    vec3 d = vec3(p,0);
    if(1. - dot(d,d) < -0.000001) {
        return;
    }
    d.z = sqrt(1. - dot(d,d) * 0.999999);
    d.xz *= mat2(cos(iTime * rsp),sin(iTime * rsp),-sin(iTime * rsp),cos(iTime * rsp));
    vec3 j = shine(texture(iChannel0,d).xyz);
    c.xyz += j;
    c = mix(c,max(c,0.),0.5);
}

void mainImage(out vec4 c,vec2 p) {
    c = texture(iChannel1,p / r) * 0.5;
    for(float x = 0.;x < 5.;x++)
    for(float y = 0.;y < 5.;y++) {
        c += texture(iChannel0,(p - vec2(x - 2.,y - 2.) * blur) / r) * 0.04;
    }
}

