void mainImage(out vec4 c,vec2 p) {
    c = texture(iChannel1,p / r) * 0.5;
    for(float x = 0.;x < 5.;x++)
    for(float y = 0.;y < 5.;y++) {
        c += texture(iChannel0,(p - vec2(x - 2.,y - 2.) * blur * 25.) / r) * 0.04;
