vec2 mainSound(int samp,float time) {
    vec2 c = vec2(0.2);
    for(float i; i++ < 8.;) {
        c *= sin((fract(time / 30.) + vec2(0,1)) * 30. * (1000. + 5. * exp(i * 0.3))) * 0.8 + 1.;
    }
    return c;
}
